// ── Geometry constants ──────────────────────────────────────────────
var field = { x0: 120, x1: 565, y0: 25, y1: 380 };
var E_MIN = -1.35, E_MAX = 1.35;
function sy(e) { return field.y1 - (e - E_MIN) / (E_MAX - E_MIN) * (field.y1 - field.y0); }
function sx(t) { return field.x0 + 22 + t * (field.x1 - field.x0 - 44); }

// ── State ───────────────────────────────────────────────────────────
var state = { h: 0.25, dg: -0.6, label: '(a)' };
var profiles = {
  a: { h: 0.25, dg: -0.6, label: '(a)' },
  b: { h: 0.85, dg: -0.4, label: '(b)' },
  c: { h: 0.20, dg: 0.15, label: '(c)' },
  d: { h: 0.95, dg: 0.5,  label: '(d)' }
};

function smoothstep(u) { return u * u * (3 - 2 * u); }
function curveE(t) {
  var h = state.h, dg = state.dg;
  var peak = Math.max(h, dg + 0.1); // peak always above both endpoints
  if (t < 0.18) return 0;
  if (t < 0.52) return peak * smoothstep((t - 0.18) / 0.34);
  if (t < 0.86) return peak + (dg - peak) * smoothstep((t - 0.52) / 0.34);
  return dg;
}

// ── Static scaffold: energy arrow, field, axes ──────────────────────
var grad = draw.gradient('linear', function (add) {
  add.stop(0, '#fdeecb'); add.stop(1, '#f08338');
}).from(0, 1).to(0, 0);
// arrow: shaft + head
draw.polygon('52,395 86,395 86,55 100,55 69,12 38,55 52,55').fill(grad).stroke({ color: '#333', width: 1.2 });
draw.text('Energy').font({ size: 16, family: 'sans-serif', weight: 'bold' })
  .center(69, 205).rotate(-90, 69, 205);

draw.rect(field.x1 - field.x0, field.y1 - field.y0).move(field.x0, field.y0)
  .fill('#dceef7').stroke('none');
// axes
draw.line(field.x0, field.y0, field.x0, field.y1).stroke({ color: '#222', width: 2 });
draw.line(field.x0, field.y1, field.x1, field.y1).stroke({ color: '#222', width: 2 });

// Reaction progress label + magenta arrowhead
draw.text('Reaction progress').font({ size: 16, family: 'sans-serif' })
  .attr('text-anchor', 'end').move(field.x1 - 130, field.y1 + 22);
draw.line(field.x1 - 120, field.y1 + 32, field.x1 - 18, field.y1 + 32)
  .stroke({ color: '#d63384', width: 3 });
draw.polygon('0,-7 16,0 0,7').move(field.x1 - 18, field.y1 + 32).fill('#d63384');

// panel label
