// ── Dynamic layer ───────────────────────────────────────────────────
var dyn = draw.group();
var HALO = { 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' };

function redraw() {
  dyn.clear();
  var h = state.h, dg = state.dg;
  var peak = Math.max(h, dg + 0.1);
  var yR = sy(0), yP = sy(peak), yPr = sy(dg);
  var tPeak = 0.52, xPeak = sx(tPeak);
  var i, pts = [];
  for (i = 0; i <= 160; i++) {
    var t = i / 160;
    pts.push([sx(t), sy(curveE(t))]);
  }

  // dashed reference lines
  var dash = { color: '#333', width: 1.4, dasharray: '6,4' };
  dyn.line(sx(0.02), yR, sx(0.42), yR).stroke(dash);            // reactant level
  dyn.line(sx(0.30), yP, sx(0.72), yP).stroke(dash);           // peak level
  dyn.line(sx(0.60), yPr, sx(0.98), yPr).stroke(dash);         // product level

  // magenta curve
  dyn.polyline(pts.map(function (p) { return p.join(','); }).join(' '))
    .fill('none').stroke({ color: '#d63384', width: 4, linecap: 'round', linejoin: 'round });

  // ── ΔG‡ double arrow (reactant → peak), placed left of peak ──
  var xDag = sx(0.32);
  dyn.line(xDag, yR, xDag, yP).stroke({ color: '#333', width: 1.4 });
  dyn.polygon('0,6 -5,-4 5,-4').move(xDag, yR - 6).fill('#333');       // up arrowhead at peak... draw both heads
  dyn.polygon('0,-6 -5,4 5,4').move(xDag, yP + 6).fill('#333');
  var dagVal = (peak - 0);
  var tDag = dyn.text('ΔG‡ = ' + dagVal.toFixed(2)).font({ size: 14, family: 'sans-serif' }).attr(HALO);
  tDag.attr('text-anchor', 'end').move(xDag - 10, (yR + yP) / 2 - 18);
  var dagBg = dyn.line(sx(0.32), yR, sx(0.32), yP); // keep reference

  // ── ΔG° double arrow (reactant → product), placed right ──
  var xDg = sx(0.90);
  dyn.line(xDg, yR, xDg, yPr).stroke({ color: '#333', width: 1.4 });
  dyn.polygon('0,-6 -5,4 5,4').move(xDg, Math.min(yR, yPr) + (yR < yPr ? 6 : 6)).fill('#333');
  // arrowheads: top head points up, bottom head points down
  dyn.polygon('0,-6 -5,4 5,4').move(xDg, Math.min(yR, yPr) + 6).fill('#333');
  dyn.polygon('0,6 -5,-4 5,-4').move(xDg, Math.max(yR, yPr) - 6).fill('#333');
  var tDg = dyn.text('ΔG° = ' + (dg >= 0 ? '+' : '') + dg.toFixed(2))
    .font({ size: 14, family: 'sans-serif' }).attr(HALO);
  tDg.attr('text-anchor', 'start').move(xDg + 10, (yR + yPr) / 2 - 18);

  // kinetic / thermo annotation
  var rate = h < 0.4 ? 'fast (low barrier)' : h < 0.7 ? 'moderate barrier' : 'slow (high barrier)';
  var thermo = dg < -0.05 ? 'exergonic — favorable' : dg > 0.05 ? 'endergonic — unfavorable' : 'ΔG° ≈ 0';
