    .attr(HALO).attr('text-anchor', 'middle')
    .move((field.x0 + field.x1) / 2 - 60, field.y1 - 24);

  // hover on curve region
  var hit = dyn.rect(field.x1 - field.x0 - 20, field.y1 - field.y0 - 20)
    .move(field.x0 + 10, field.y0 + 10).fill('#fff').opacity(0).back();
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) {
    showTooltip('ΔG‡ sets the rate; ΔG° sets favorability — they vary independently', e);
  }).on('mouseleave', function () { hideTooltip(); })
   .on('click', function () {
     showPopup('Kinetics vs. Thermodynamics',
       'The activation barrier ΔG‡ (reactants → peak) controls how fast the reaction goes, while ΔG° (reactants → products) controls whether it is favorable. Either can be large or small independently, giving four combinations: fast/slow × exergonic/endergonic.');
   });

  panelLabel.text(state.label);
}

