// @FIGURE_CODE_BEGIN
var W = 600, H = 470;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

// ── Geometry constants ──────────────────────────────────────────────
var field = { x0: 120, x1: 565, y0: 25, y1: 380 };
var E_MIN = -1.35, E_MAX = 1.35;
function sy(e) { return field.y1 - (e - E_MIN) / (E_MAX - E_MIN) * (field.y1 - field.y0); }
function sx(t) { return field.x0 + 22 + t * (field.x1 - field.x0 - 44); }

// ── State ───────────────────────────────────────────────────────────
var state = { h: 0.25, dg: -0.6, label: '(a)' };
var profiles = {
  a: { h: 0.25, dg: -0.6, label: '(a)' },
  b: { h: 0.85, dg: -0.4, label: '(b)' },
  c: { h: 0.20, dg: 0.15, label: '(c)' },
  d: { h: 0.95, dg: 0.5,  label: '(d)' }
};

function smoothstep(u) { return u * u * (3 - 2 * u); }
function curveE(t) {
  var h = state.h, dg = state.dg;
  var peak = Math.max(h, dg + 0.1); // peak always above both endpoints
  if (t < 0.18) return 0;
  if (t < 0.52) return peak * smoothstep((t - 0.18) / 0.34);
  if (t < 0.86) return peak + (dg - peak) * smoothstep((t - 0.52) / 0.34);
  return dg;
}

// ── Static scaffold: energy arrow, field, axes ──────────────────────
var grad = draw.gradient('linear', function (add) {
  add.stop(0, '#fdeecb'); add.stop(1, '#f08338');
}).from(0, 1).to(0, 0);
draw.polygon('52,395 86,395 86,55 100,55 69,12 38,55 52,55').fill(grad).stroke({ color: '#333', width: 1.2 });
draw.text('Energy').font({ size: 16, family: 'sans-serif', weight: 'bold' })
  .center(69, 205).rotate(-90, 69, 205);

draw.rect(field.x1 - field.x0, field.y1 - field.y0).move(field.x0, field.y0)
  .fill('#dceef7').stroke('none');
draw.line(field.x0, field.y0, field.x0, field.y1).stroke({ color: '#222', width: 2 });
draw.line(field.x0, field.y1, field.x1, field.y1).stroke({ color: '#222', width: 2 });

// Reaction progress label + magenta arrowhead
draw.text('Reaction progress').font({ size: 16, family: 'sans-serif' })
  .attr('text-anchor', 'end').move(field.x1 - 130, field.y1 + 22);
draw.line(field.x1 - 120, field.y1 + 32, field.x1 - 18, field.y1 + 32)
  .stroke({ color: '#d63384', width: 3 });
draw.polygon('0,-7 16,0 0,7').move(field.x1 - 18, field.y1 + 32).fill('#d63384');

// panel label
var panelLabel = draw.text('(a)').font({ size: 15, family: 'sans-serif' }).move(14, 30);

// ── Dynamic layer ───────────────────────────────────────────────────
var dyn = draw.group();
var HALO = { 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' };

function redraw() {
  dyn.clear();
  var h = state.h, dg = state.dg;
  var peak = Math.max(h, dg + 0.1);
  var yR = sy(0), yP = sy(peak), yPr = sy(dg);
  var i, pts = [];
  for (i = 0; i <= 160; i++) {
    var t = i / 160;
    pts.push([sx(t), sy(curveE(t))]);
  }

  // dashed reference lines
  var dash = { color: '#333', width: 1.4, dasharray: '6,4' };
  dyn.line(sx(0.02), yR, sx(0.42), yR).stroke(dash);    // reactant level
  dyn.line(sx(0.30), yP, sx(0.72), yP).stroke(dash);    // peak level
  dyn.line(sx(0.60), yPr, sx(0.98), yPr).stroke(dash);  // product level

  // magenta curve
  dyn.polyline(pts.map(function (p) { return p.join(','); }).join(' '))
    .fill('none').stroke({ color: '#d63384', width: 4, linecap: 'round', linejoin: 'round' });

  // ── ΔG‡ double arrow (reactant → peak) ──
  var xDag = sx(0.32);
  dyn.line(xDag, yR, xDag, yP).stroke({ color: '#333', width: 1.4 });
  dyn.polygon('0,-6 -5,4 5,4').move(xDag, yP + 6).fill('#333');  // head at top (peak)
  dyn.polygon('0,6 -5,-4 5,-4').move(xDag, yR - 6).fill('#333'); // head at bottom (reactant)
  var tDag = dyn.text('ΔG‡').font({ size: 16, family: 'sans-serif' }).attr(HALO);
  tDag.attr('text-anchor', 'end').move(xDag - 10, (yR + yP) / 2 - 9);

  // ── ΔG° double arrow (reactant → product), placed right ──
  var xDg = sx(0.90);
  var yTop = Math.min(yR, yPr), yBot = Math.max(yR, yPr);
  dyn.line(xDg, yTop, xDg, yBot).stroke({ color: '#333', width: 1.4 });
  dyn.polygon('0,-6 -5,4 5,4').move(xDg, yTop + 6).fill('#333');  // head at top
  dyn.polygon('0,6 -5,-4 5,-4').move(xDg, yBot - 6).fill('#333'); // head at bottom
  var tDg = dyn.text('ΔG°').font({ size: 16, family: 'sans-serif' }).attr(HALO);
  // keep the label inside the light-blue field
  var dgMidY = (yR + yPr) / 2 - 9;
  var dgLabelW = 34;
  if (xDg + 10 + dgLabelW > field.x1 - 6) {
    tDg.attr('text-anchor', 'end').move(xDg - 10, dgMidY);
  } else {
    tDg.attr('text-anchor', 'start').move(xDg + 10, dgMidY);
  }

  // hover / click target
  var hit = dyn.rect(field.x1 - field.x0 - 20, field.y1 - field.y0 - 20)
    .move(field.x0 + 10, field.y0 + 10).fill('#fff').opacity(0).back();
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) {
    var rate = h < 0.4 ? 'fast (low barrier)' : h < 0.7 ? 'moderate barrier' : 'slow (high barrier)';
    var thermo = dg < -0.05 ? 'exergonic — favorable' : dg > 0.05 ? 'endergonic — unfavorable' : 'ΔG° ≈ 0';
    showTooltip('ΔG‡ = ' + peak.toFixed(2) + ' → ' + rate + ' · ΔG° = ' + (dg >= 0 ? '+' : '') + dg.toFixed(2) + ' → ' + thermo, e);
  }).on('mouseleave', function () { hideTooltip(); })
   .on('click', function () {
     showPopup('Kinetics vs. Thermodynamics',
       'The activation barrier ΔG‡ (reactants → peak) controls how fast the reaction goes, while ΔG° (reactants → products) controls whether it is favorable. Either can be large or small independently, giving four combinations: fast/slow × exergonic/endergonic.');
   });

  panelLabel.text(state.label);
}

// ── Interaction handlers ────────────────────────────────────────────
function update_barrierHeight(v) {
  state.h = v; state.label = '(custom)';
  document.getElementById('profileTypeInput').value = '';
  redraw();
}
function update_productEnergy(v) {
  state.dg = v; state.label = '(custom)';
  document.getElementById('profileTypeInput').value = '';
  redraw();
}
function update_profileType(v) {
  if (!profiles[v]) return;
  var p = profiles[v];
  state.h = p.h; state.dg = p.dg; state.label = p.label;
  document.getElementById('barrierHeightInput').value = p.h;
  document.getElementById('barrierHeightVal').value = p.h;
  document.getElementById('productEnergyInput').value = p.dg;
  document.getElementById('productEnergyVal').value = p.dg;
  redraw();
}

// ── Demo step player ────────────────────────────────────────────────
var steps = [
  { key: 'a', title: 'Fast exergonic',
    narration: 'Panel (a): a low barrier means the reaction is fast, and products sit well below reactants so ΔG° is negative — the reaction is both fast and favorable.' },
  { key: 'b', title: 'Slow exergonic',
    narration: 'Panel (b): the products are still downhill, but the tall barrier makes the reaction slow — thermodynamic favorability does not guarantee speed.' },
  { key: 'c', title: 'Fast endergonic',
    narration: 'Panel (c): a shallow hump makes it fast, but products end slightly above reactants, so ΔG° is positive — a fast reaction can still be unfavorable.' },
  { key: 'd', title: 'Slow endergonic',
    narration: 'Panel (d): a very tall barrier plus products above reactants — slow and unfavorable. Now drag the two sliders yourself and watch the profile morph continuously between all four types.' }
];
var stepIdx = 0;
function showStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('profileTypeInput').value = s.key;
  update_profileType(s.key);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length + ' ' + s.title;
}
function nextStep() { showStep(stepIdx + 1); }
function prevStep() { showStep(stepIdx - 1); }

redraw();
showStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A reaction's rate is set by its activation barrier (ΔG‡) while its thermodynamic favorability is set by the product–reactant energy difference (ΔG°), and these two quantities vary independently to produce the four distinct reaction profiles shown in the textbook's 2×2 grid.
KEY INSIGHT (what students should walk away understanding): ΔG‡ (kinetics) and ΔG° (thermodynamics) are independent: any barrier height can pair with any product energy, which is why 'fast' and 'favorable' are separate questions about a reaction.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A reaction's rate is set by its activation barrier (ΔG‡) while its thermodynamic favorability is set by the product–reactant energy difference (ΔG°), and these two quantities vary independently to produce the four distinct reaction profiles shown in the textbook's 2×2 grid.",
  "figureType": "diagram",
  "elements": [
    "2×2 grid of four panels shown in 'all four' view, each labeled (a), (b), (c), or (d) at its upper left",
    "single enlarged panel shown in 'single profile' view, carrying the matching (a)–(d) label",
    "vertical Energy axis arrow per panel, cream-to-orange gradient, labeled 'Energy'",
    "horizontal axis per panel: 'Reaction progress' magenta text with the magenta arrowhead placed fully to the right of the text (or directly below it) so arrow and text never overlap",
    "pale blue plotting field per panel, no numeric ticks on either axis",
    "smooth magenta energy curve per panel: flat reactant plateau, single rounded maximum, flat product plateau",
    "short horizontal dashed reference segment at the reactant energy level, near the left plateau only",
    "short horizontal dashed reference segment at the transition-state (maximum) level, near the peak only",
    "short horizontal dashed reference segment at the product energy level, near the right plateau only",
    "double-headed vertical arrow between the reactant and maximum dashed segments, labeled ΔG‡",
    "double-headed vertical arrow between the reactant and product dashed segments, labeled ΔG°, positioned near the middle of the curve (not at the far right edge)"
  ],
  "interactions": [
    {
      "id": "viewMode",
      "type": "toggle",
      "label": "View",
