      "label": "Product energy (ΔG°)",
      "range": [
        -1,
        1,
        0.05
      ],
      "default": -0.6,
      "teaches": "Moving the product level above or below the reactant level flips the reaction between endergonic and exergonic without changing the barrier height"
    }
  ],
  "demo_steps": [
    {
      "title": "The full 2×2 grid",
      "narration": "The default view reproduces the textbook's four panels simultaneously: barrier height (fast vs. slow) and product energy (exergonic vs. endergonic) vary independently, giving all four combinations.",
