// @FIGURE_CODE_BEGIN
var W = 640, H = 660;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var HALO = { 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' };
var E_MIN = -1.35, E_MAX = 1.35;
var MAGENTA = '#d63384';

// canonical profile values (barrier h is peak height above reactants in energy units)
var profiles = {
  a: { h: 0.25, dg: -0.6,  label: '(a)', name: 'Fast exergonic' },
  b: { h: 0.85, dg: -0.4,  label: '(b)', name: 'Slow exergonic' },
  c: { h: 0.20, dg: 0.15,  label: '(c)', name: 'Fast endergonic' },
  d: { h: 0.95, dg: 0.5,   label: '(d)', name: 'Slow endergonic' }
};

var state = { view: 'grid', key: 'a', h: 0.25, dg: -0.6 };

function smoothstep(u) { return u * u * (3 - 2 * u); }
function curveE(t, h, dg) {
  var peak = Math.max(h, dg + 0.1);
  if (t < 0.14) return 0;
  if (t < 0.50) return peak * smoothstep((t - 0.14) / 0.36);
  if (t < 0.86) return peak + (dg - peak) * smoothstep((t - 0.50) / 0.36);
  return dg;
}

// ── Panel renderer: draws one complete textbook panel ─────────────
// rect = {x,y,w,h} of the WHOLE panel cell (including energy arrow + x-axis label)
function drawPanel(g, rect, p, opts) {
  opts = opts || {};
  var big = !!opts.big;
  var fs = big ? 15 : 11;                 // font size scales with panel
  var arrowW = big ? 34 : 22;
  var axisGap = big ? 46 : 30;            // room below field for axis label
  var fx = rect.x + arrowW + (big ? 26 : 16);
  var fy = rect.y + (big ? 26 : 16);
  var fw = rect.w - (fx - rect.x) - (big ? 14 : 8);
  var fh = rect.h - (fy - rect.y) - axisGap;

  function sy(e) { return fy + fh - (e - E_MIN) / (E_MAX - E_MIN) * fh; }
  function sx(t) { return fx + fw * 0.06 + t * fw * 0.88; }

  // panel label at cell upper-left
  g.text(p.label).font({ size: big ? 16 : 12, family: 'sans-serif' }).move(rect.x + 2, rect.y + 2);

  // Energy arrow: cream-to-orange gradient
  var ax = rect.x + arrowW * 0.5 + (big ? 10 : 4);
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#fdeecb'); add.stop(1, '#f08338');
  }).from(0, 1).to(0, 0);
  var aTop = fy + (big ? 4 : 2), aBot = fy + fh - 2;
  var hw = big ? 13 : 9, hh = big ? 26 : 18, bw = big ? 8 : 6;
  g.polygon([
    [ax - bw, aBot], [ax + bw, aBot], [ax + bw, aTop + hh],
    [ax + hw, aTop + hh], [ax, aTop], [ax - hw, aTop + hh], [ax - bw, aTop + hh]
  ].map(function (q) { return q.join(','); }).join(' '))
    .fill(grad).stroke({ color: '#333', width: 1 });
  g.text('Energy').font({ size: fs, family: 'sans-serif', weight: 'bold' })
    .center(ax, (aTop + aBot) / 2).rotate(-90, ax, (aTop + aBot) / 2);

  // pale blue field + axes
  g.rect(fw, fh).move(fx, fy).fill('#dceef7').stroke('none');
  g.line(fx, fy, fx, fy + fh).stroke({ color: '#222', width: 1.6 });
  g.line(fx, fy + fh, fx + fw, fy + fh).stroke({ color: '#222', width: 1.6 });

  // Reaction progress label, then magenta arrow fully to the RIGHT of text
  var labelY = fy + fh + (big ? 14 : 9);
  var lbl = g.text('Reaction progress').font({ size: fs, family: 'sans-serif', fill: MAGENTA })
    .attr('text-anchor', 'end').move(fx + fw - (big ? 96 : 66), labelY - fs / 2 - 1);
  var arrX0 = fx + fw - (big ? 90 : 60), arrX1 = fx + fw - 2;
  g.line(arrX0, labelY, arrX1 - (big ? 10 : 7), labelY).stroke({ color: MAGENTA, width: big ? 2.5 : 1.8 });
  var ah = big ? 5 : 3.5, al = big ? 10 : 7;
  g.polygon('0,' + (-ah) + ' ' + al + ',0 0,' + ah).move(arrX1 - al, labelY).fill(MAGENTA);

  // ── curve ──
  var h = p.h, dg = p.dg;
  var peak = Math.max(h, dg + 0.1);
  var yR = sy(0), yP = sy(peak), yPr = sy(dg);
  var pts = [];
  for (var i = 0; i <= 120; i++) {
    var t = i / 120;
    pts.push([sx(t), sy(curveE(t, h, dg))]);
  }
  g.polyline(pts.map(function (q) { return q.join(','); }).join(' '))
    .fill('none').stroke({ color: MAGENTA, width: big ? 3.5 : 2.4, linecap: 'round', linejoin: 'round' });

  // ── SHORT dashed reference segments (local anchors only) ──
  var seg = fw * (big ? 0.16 : 0.17);
  var dash = { color: '#333', width: 1.2, dasharray: big ? '5,3' : '4,3' };
  // reactant level: short segment near the left plateau
  g.line(sx(0.02), yR, sx(0.02) + seg, yR).stroke(dash);
  // peak level: short segment straddling the maximum
  g.line(sx(0.50) - seg / 2, yP, sx(0.50) + seg / 2, yP).stroke(dash);
  // product level: short segment near the right plateau
  g.line(sx(0.98) - seg, yPr, sx(0.98), yPr).stroke(dash);

  // ── ΔG‡ double arrow: reactant → peak, on the rising slope ──
  var xDag = sx(0.26);
  var ahS = big ? 5 : 3.5, ahL = big ? 7 : 5;
  g.line(xDag, yR, xDag, yP).stroke({ color: '#333', width: 1.1 });
  g.polygon('0,' + (-ahL) + ' ' + (-ahS) + ',0 ' + ahS + ',0').move(xDag, yP).fill('#333');
  g.polygon('0,' + ahL + ' ' + (-ahS) + ',0 ' + ahS + ',0').move(xDag, yR).fill('#333');
  g.text('ΔG‡').font({ size: fs + 1, family: 'sans-serif' }).attr(HALO)
    .attr('text-anchor', 'end').move(xDag - (big ? 7 : 5), (yR + yP) / 2 - (fs + 1) / 2);

  // ── ΔG° double arrow: reactant → product, near curve MIDDLE ──
  var xDg = sx(0.56);
  var yTop = Math.min(yR, yPr), yBot = Math.max(yR, yPr);
  g.line(xDg, yTop, xDg, yBot).stroke({ color: '#333', width: 1.1 });
  g.polygon('0,' + (-ahL) + ' ' + (-ahS) + ',0 ' + ahS + ',0').move(xDg, yTop).fill('#333');
  g.polygon('0,' + ahL + ' ' + (-ahS) + ',0 ' + ahS + ',0').move(xDg, yBot).fill('#333');
  // label to the side with more room, kept inside the field
  var dgMidY = (yTop + yBot) / 2 - (fs + 1) / 2;
  var dgTxt = g.text('ΔG°').font({ size: fs + 1, family: 'sans-serif' }).attr(HALO);
  if (xDg + (big ? 8 : 6) + 30 < fx + fw) {
    dgTxt.attr('text-anchor', 'start').move(xDg + (big ? 8 : 6), dgMidY);
  } else {
    dgTxt.attr('text-anchor', 'end').move(xDg - (big ? 8 : 6), dgMidY);
  }
}

// ── Views ─────────────────────────────────────────────────────────
var root = draw.group();

function redraw() {
  root.clear();
  if (state.view === 'grid') {
    var cw = W / 2, ch = H / 2;
    var keys = ['a', 'b', 'c', 'd'];
    for (var i = 0; i < 4; i++) {
      var k = keys[i];
      var rect = { x: (i % 2) * cw + 4, y: Math.floor(i / 2) * ch + 4, w: cw - 8, h: ch - 8 };
      var cell = root.group();
      drawPanel(cell, rect, profiles[k], { big: false });
      // invisible hit rect → click isolates this panel
      (function (key, cell) {
        var hit = cell.rect(cw - 8, ch - 8).move((keys.indexOf(key) % 2) * cw + 4, Math.floor(keys.indexOf(key) / 2) * ch + 4)
          .fill('#fff').opacity(0);
        hit.css('cursor', 'pointer');
        hit.on('mousemove', function (e) {
          var p = profiles[key];
          showTooltip(p.label + ' ' + p.name + ' — click to enlarge (ΔG‡=' + Math.max(p.h, p.dg + 0.1).toFixed(2) + ', ΔG°=' + (p.dg >= 0 ? '+' : '') + p.dg.toFixed(2) + ')', e);
        }).on('mouseleave', function () { hideTooltip(); })
         .on('click', function () {
           hideTooltip();
           document.getElementById('viewModeInput').value = 'single';
           update_profileType(key);
           update_viewMode('single');
           showPopup('Profile ' + profiles[key].label + ' — ' + profiles[key].name,
             'ΔG‡ (reactants → peak) sets the rate: low barrier = fast. ΔG° (reactants → products) sets favorability: negative = exergonic. The two vary independently — use the sliders to morph this panel into any of the other three.');
         });
      })(k, cell);
    }
  } else {
    drawPanel(root, { x: 6, y: 6, w: W - 12, h: H - 12 },
      { h: state.h, dg: state.dg, label: state.label || profiles[state.key].label }, { big: true });
    var hit = root.rect(W - 12, H - 12).move(6, 6).fill('#fff').opacity(0).back();
    hit.css('cursor', 'pointer');
    hit.on('mousemove', function (e) {
      var rate = state.h < 0.4 ? 'fast (low barrier)' : state.h < 0.7 ? 'moderate barrier' : 'slow (high barrier)';
      var thermo = state.dg < -0.05 ? 'exergonic — favorable' : state.dg > 0.05 ? 'endergonic — unfavorable' : 'ΔG° ≈ 0';
      showTooltip('ΔG‡ → ' + rate + ' · ΔG° = ' + (state.dg >= 0 ? '+' : '') + state.dg.toFixed(2) + ' → ' + thermo, e);
    }).on('mouseleave', function () { hideTooltip(); })
     .on('click', function () {
       showPopup('Kinetics vs. Thermodynamics',
         'The activation barrier ΔG‡ controls how fast the reaction goes, while ΔG° controls whether it is favorable. Either can be large or small independently — that is why the textbook needs four separate panels.');
     });
  }
}

